  const load=()=>{ setLoading(true); const cbName="psl_cb_"+Date.now(); const old=document.getElementById("psl_jsonp"); if(old) old.remove(); const timeoutId=setTimeout(()=>{setLoading(false); showToast("Load timeout - Deploy NEW VERSION");},10000); window[cbName]=(d)=>{ clearTimeout(timeoutId); try{ const arr=Array.isArray(d)?d:(d.data||[]); const withId=arr.map((row,i)=>{ const ts=(row.Timestamp||row.timestamp||"")+""; if(!ts||ts.trim()===""||ts==="undefined") return null; let saved={}; try{saved=JSON.parse(localStorage.getItem(`psl_${ts}`)||'{}')}catch{} const norm={...row,Timestamp:ts,timestamp:ts,Status:saved.Status||row.Status||row.status||'New',_uid:`${ts}_${i}`,_index:i}; if(norm.FullName) norm.FullName=titleCase(norm.FullName); return norm; }).filter(Boolean); setData(withId.sort((a,b)=>parseTs(a.timestamp)-parseTs(b.timestamp))); let repliedSet=new Set(); try{repliedSet=new Set(JSON.parse(localStorage.getItem('psl_auto_replied')||'[]'))}catch{} const settings=autoSettingsRef.current; let newReplied=[...repliedSet]; let newCount=0; withId.forEach(row=>{ const ts=row.Timestamp; if(prevTimestampsRef.current.has(ts)) return; if(repliedSet.has(ts)) return; const isNewRow=prevTimestampsRef.current.size>0; if(isNewRow&&settings.emailOn&&getVal(row,['Email','email'])){ const isApp=isApplicantRow(row); const subject=isApp?`Pinnacle Security Ltd - Your Application for ${getVal(row,['Position','position'])||'Security Officer'} - Received`:`Pinnacle Security Ltd - Your ${getVal(row,['Service','service'])||'Security Service'} Enquiry - Received`; const body=fillTemplate(isApp?settings.applicantEmail:settings.contactEmail,row); fetch(GOOGLE_SHEET_WEBHOOK,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain'},body:JSON.stringify({action:'autoReplyEmail',Timestamp:ts,to:getVal(row,['Email','email']),subject,body})}); newReplied.push(ts); repliedSet.add(ts); newCount++; } }); if(newCount>0) showToast(`${newCount} new - Auto Email sent`); if(newReplied.length>0){ try{ const oldLen=JSON.parse(localStorage.getItem('psl_auto_replied')||'[]').length; if(newReplied.length!==oldLen){ localStorage.setItem('psl_auto_replied',JSON.stringify(newReplied)); setAutoReplied(newReplied); } }catch{} } withId.forEach(r=>prevTimestampsRef.current.add(r.Timestamp)); }catch(e){console.log(e)} setLoading(false); delete window[cbName]; const sc=document.getElementById("psl_jsonp"); if(sc) sc.remove(); }; const s=document.createElement("script"); s.id="psl_jsonp"; s.src=GOOGLE_SHEET_WEBHOOK+"?callback="+cbName+"&cache="+Date.now(); s.onerror=()=>{clearTimeout(timeoutId); setLoading(false); delete window[cbName]; const sc=document.getElementById("psl_jsonp"); if(sc) sc.remove(); showToast("Load failed - Deploy NEW VERSION, Access = Anyone");}; document.body.appendChild(s); };
  useEffect(()=>{if(auth) load();},[auth]); useEffect(()=>{setCurrentPage(1)},[search,tab,rowsPerPage,filters,sortBy]);
  const formatDate=(ts)=>{ if(!ts) return ''; const str=String(ts); if(str.includes('/')) return str.slice(0,16); const d=new Date(str); if(isNaN(d.getTime())) return str.slice(0,16); try{ const p=new Intl.DateTimeFormat('en-GB',{timeZone:'Africa/Kampala',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(d); const g=(t)=>p.find(x=>x.type===t)?.value||''; return `${g('day')}/${g('month')}/${g('year')} ${g('hour')}:${g('minute')}`; }catch{ return `${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()} ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`; } };
